// Once generated by CoffeeScript 1.9.3, but now lives as pure JS
/* eslint-disable */
(function() {
  var getCookieValue, getUsernameFromEdxUserCookie, isSameOriginRequest;

  getCookieValue = function(name) {
    var match;
    match = document.cookie.match(new RegExp("(^|;)\\s*" + name + "\\s*=\\s*([^;]+)"));
    return match ? match.pop() : null;
  };

  getUsernameFromEdxUserCookie = function() {
    var parsed, userCookie;
    userCookie = getCookieValue('edx-user-info') || $.cookie('edx-user-info');
    if (!userCookie) {
      return null;
    }
    try {
      // Match existing parsing logic used in student_account utils.
      parsed = userCookie.replace(/\\/g, '').replace(/054/g, ',');
      parsed = parsed.substring(1, parsed.length - 1);
      parsed = JSON.parse(parsed);
      return parsed && parsed.username ? parsed.username : null;
    } catch (error) {
      return null;
    }
  };

  isSameOriginRequest = function(url) {
    var a;
    if (!url || /^\/(?!\/)/.test(url)) {
      return true;
    }
    a = document.createElement('a');
    a.href = url;
    return a.protocol === window.location.protocol && a.host === window.location.host;
  };

  AjaxPrefix.addAjaxPrefix(jQuery, function() {
    return $("meta[name='path_prefix']").attr('content');
  });

  $(function() {
    $.ajaxSetup({
      headers: {
        'X-CSRFToken': $.cookie('csrftoken')
      },
      beforeSend: function(xhr, settings) {
        var csrfToken, hasUserHeader, username;
        csrfToken = $.cookie('csrftoken');
        if (csrfToken) {
          xhr.setRequestHeader('X-CSRFToken', csrfToken);
        }

        if (!isSameOriginRequest(settings && settings.url)) {
          return;
        }
        hasUserHeader = settings && settings.headers && settings.headers['X-User-Id'];
        if (hasUserHeader) {
          return;
        }
        username = getUsernameFromEdxUserCookie();
        if (username) {
          xhr.setRequestHeader('X-User-Id', username);
        }
      },
      dataType: 'json'
    });
    window.onTouchBasedDevice = function() {
      return navigator.userAgent.match(/iPhone|iPod|iPad|Android/i);
    };
    if (onTouchBasedDevice()) {
      $('body').addClass('touch-based-device');
    }

    /*
    $("a[rel*=leanModal]").leanModal()
     */
    $('#csrfmiddlewaretoken').attr('value', $.cookie('csrftoken'));
    new Calculator;
    new FeedbackForm;
    if ($('body').hasClass('courseware')) {
      Courseware.start();
    }
    window.postJSON = function(url, data, callback) {
      return $.postWithPrefix(url, data, callback);
    };
    $('#login').click(function() {
      $('#login_form input[name="email"]').focus();
      return false;
    });
    $('#signup').click(function() {
      $('#signup-modal input[name="email"]').focus();
      return false;
    });

    /*
    fix for ie
     */
    if (!Array.prototype.indexOf) {
      return Array.prototype.indexOf = function(obj, start) {
        var ele, i, j, len, ref;
        if (start == null) {
          start = 0;
        }
        ref = this.slice(start);
        for (i = j = 0, len = ref.length; j < len; i = ++j) {
          ele = ref[i];
          if (ele === obj) {
            return i + start;
          }
          return -1;
        }
      };
    }
  });

}).call(this);
